    project_id, scope, status, created_at, updated_at, closed_at, version,
    metadata_schema_version, metadata_payload, metadata_hash
) VALUES (
    #{row.sessionId}, #{row.schemaVersion}, #{row.tenantId}, #{row.ownerPrincipalId},
    #{row.ownerPrincipalType}, #{row.projectId}, #{row.scope}, #{row.status},
    #{row.createdAt}, #{row.updatedAt}, #{row.closedAt}, #{row.version},
    #{row.metadataSchemaVersion}, #{row.metadataPayload}, #{row.metadataHash}
)

mapper.select:
SELECT  FROM session_message
WHERE session_id = #{sessionId} AND sequence > #{cursor}
ORDER BY sequence ASC LIMIT #{limit}

SELECT * FROM (
    SELECT  FROM session_message
    WHERE session_id = #{sessionId} AND sequence <= #{cursor}
    ORDER BY sequence DESC LIMIT #{limit}
) ORDER BY sequence ASC

