INSERT INTO runtime_event_stream (
    run_id, head_sequence, earliest_sequence, updated_at
) VALUES (
    #{runId}, #{headSequence}, #{earliestSequence}, #{updatedAt}
)
ON CONFLICT(run_id) DO NOTHING

mapper.update:
UPDATE runtime_event_stream
SET head_sequence = #{newHead},
    earliest_sequence = CASE
        WHEN head_sequence = 0 THEN #{newHead}
        ELSE earliest_sequence
    END,
    updated_at = #{updatedAt}
WHERE run_id = #{runId} AND head_sequence = #{expectedHead}

