SELECT  FROM runtime_event
WHERE run_id = #{runId}
  AND sequence > #{exclusiveSequence}
  AND sequence <= #{observedHead}
ORDER BY sequence ASC
LIMIT #{limit}

mapper.delete:
DELETE FROM outbox
WHERE run_id = #{runId}
  AND sequence < #{retainFromSequence}
  AND published_at IS NOT NULL

DELETE FROM runtime_event
WHERE run_id = #{runId}
  AND sequence < #{retainFromSequence}
  AND NOT EXISTS (
      SELECT 1 FROM outbox
      WHERE outbox.event_id = runtime_event.event_id
  )

