mapper.insert:
INSERT INTO idempotency (
    caller_scope, operation, idempotency_key, run_id, request_digest, command_applied,
    result_schema_version, result_payload, result_hash, created_at, updated_at
) VALUES (
    #{row.callerScope}, #{row.operation}, #{row.idempotencyKey}, #{row.runId},
    #{row.requestDigest},
    #{row.commandApplied}, #{row.resultSchemaVersion}, #{row.resultPayload},
    #{row.resultHash}, #{row.createdAt}, #{row.updatedAt}
)
ON CONFLICT(caller_scope, operation, idempotency_key) DO NOTHING

mapper.update:
UPDATE idempotency SET command_applied = 1, updated_at = #{updatedAt}
WHERE caller_scope = #{callerScope} AND operation = 'command'
  AND idempotency_key = #{key} AND command_applied = 0

UPDATE idempotency SET
    result_schema_version = #{row.resultSchemaVersion},
    result_payload = #{row.resultPayload}, result_hash = #{row.resultHash},
    updated_at = #{row.updatedAt}
WHERE caller_scope = #{row.callerScope} AND operation = #{row.operation}
  AND idempotency_key = #{row.idempotencyKey} AND result_payload IS NULL

UPDATE tool_journal SET state = #{row.state},
    result_schema_version = #{row.resultSchemaVersion},
    result_payload = #{row.resultPayload}, result_hash = #{row.resultHash},
    dispatch_execution_id = #{row.dispatchExecutionId},
    dispatch_process_id = #{row.dispatchProcessId},
    dispatch_workdir_digest = #{row.dispatchWorkdirDigest},
    reconcile_status = #{row.reconcileStatus}, reconcile_reason = #{row.reconcileReason},
    updated_at = #{row.updatedAt}
WHERE run_id = #{row.runId} AND idempotency_key = #{row.idempotencyKey}
  AND state = #{expectedState}

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM tool_journal WHERE run_id = #{runId} AND state = 'OUTCOME_UNKNOWN'
)

SELECT 
FROM interaction_request
WHERE run_id = #{runId} AND state = 'PENDING'
  AND expires_at IS NOT NULL AND expires_at <= #{at}
ORDER BY expires_at ASC, request_id ASC
LIMIT #{limit}

SELECT 
FROM interaction_response
WHERE caller_scope = #{callerScope}
  AND request_id = #{requestId}
  AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE interaction_request
SET state = 'RESPONDED', revision = revision + 1, state_changed_at = #{changedAt},
    state_reason_code = NULL
WHERE request_id = #{requestId}
  AND revision = #{expectedRevision}
  AND state = 'PENDING'

UPDATE interaction_request
SET state = #{targetState}, revision = revision + 1,
    state_reason_code = #{reasonCode}, state_changed_at = #{changedAt}
WHERE request_id = #{requestId}
  AND revision = #{expectedRevision}
  AND state = #{expectedState}

UPDATE interaction_request
SET state = 'APPLIED', revision = revision + 1, state_changed_at = #{appliedAt}
WHERE request_id = #{requestId}
  AND revision = #{expectedRevision}
  AND state = 'RESPONDED'

UPDATE interaction_application SET resolution_applied = 1, applied_at = #{appliedAt}
WHERE request_id = #{requestId} AND resolution_applied = 0
  AND EXISTS (
      SELECT 1 FROM interaction_response response
      WHERE response.request_id = interaction_application.request_id
  )

mapper.select:
SELECT 
FROM run_input
WHERE caller_scope = #{callerScope}
  AND run_id = #{runId}
  AND idempotency_key = #{idempotencyKey}

SELECT run_id, retrieval_policy_version, query_digest, memories_schema_version,
       memories_payload, memories_hash, updated_at
FROM memory_selection WHERE run_id = #{runId}

mapper.update:
UPDATE skill_resource_usage
SET bytes_read = bytes_read + #{bytes}, updated_at = #{updatedAt}
WHERE run_id = #{runId} AND bytes_read + #{bytes} <= #{maximum}

